mapper.select:
SELECT rownum indexNo, seqno, infoType, sd1.item_value infoTypeText, infoName, /**su.real_name approveUser,**/ infoStatus, sd2.item_value infoStatusText, infoDevStatus, sd3.item_value infoDevStatusText, to_char(updateTime,'yyyy/MM/dd hh24:mi') updateTimeText FROM ( SELECT info.seqno seqno, info.info_type infoType, info.info_name infoName, /**DECODE(info.info_status,NULL,info.create_user,s1.hi_user) userName,**/ info.info_status infoStatus, info.info_dev_status infoDevStatus, info.UPDATE_TIME updateTime FROM INFO_COMPLIANCE info /**LEFT JOIN ( select s1.seq_no,s1.hi_user,row_number() over(partition by seq_no order by his_no desc) his_no from sys_wfl_business_node s1 )s1 ON info.workflow_id = s1.seq_no and s1.his_no = 1 and info.info_status !='02'**/ WHERE INFO_STATUS IN('01','02')/**保存按钮的数据,不显示**/
AND INFO_TYPE = #{infoType,jdbcType=VARCHAR}
AND INFO_NAME LIKE concat(concat('%',#{infoName,jdbcType=VARCHAR}),'%')
AND INFO_STATUS = #{infoStatus,jdbcType=VARCHAR}
) t1 left join sys_datadict_list sd1 ON sd1.dict_code ='INFO_TYPE' AND t1.infotype = sd1.item_code left join sys_datadict_list sd2 ON sd2.dict_code = 'INFO_STATUS' AND t1.infostatus = sd2.item_code left join sys_datadict_list sd3 ON sd3.dict_code = 'INFO_DEV_STATUS' AND t1.infodevstatus = sd3.item_code /**left join sys_user su on t1.username = su.user_name**/ order by t1.updateTime desc

SELECT SEQNO seqno, INFO_TYPE infoType, INFO_NAME infoName, INFO_STATUS infoStatus, INFO_DEV_STATUS infoDevStatus, CREATE_USER createUser, REMARK remark, WORKFLOW_ID workflowId FROM INFO_COMPLIANCE
AND WORKFLOW_ID = #{workflowId,jdbcType=VARCHAR}
AND SEQNO = #{seqno,jdbcType=VARCHAR}

mapper.delete:
delete from INFO_COMPLIANCE
where 1 = 1

	AND seqno = #{seqno,jdbcType=VARCHAR}


	AND WORKFLOW_ID = #{workflowId,jdbcType=VARCHAR}

mapper.update:
UPDATE INFO_COMPLIANCE


		INFO_DEV_STATUS = #{infoDevStatus,jdbcType=VARCHAR},


		INFO_STATUS = #{infoStatus,jdbcType=VARCHAR},


		UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP},


		UPDATE_USER = #{updateUser,jdbcType=VARCHAR}


WHERE SEQNO = #{seqno,jdbcType=VARCHAR}

mapper.select:
		SELECT s1.SEQ_NO as seqNo, s1.FILE_NAME as fileName,
		s1.PATH as "path", s1.BUSINESS_ID as businessId,s1.SEQ_NO fileNo,to_char(s1.CREATE_TIME,'yyyy/MM/dd hh24:mi') createTimeText,
        s2.real_name uploadUser
		FROM SYS_UPLOAD_FILE_INFO s1
        LEFT JOIN SYS_USER s2 ON s1.create_user = s2.user_name
		WHERE BUSINESS_ID = #{businessId,jdbcType=VARCHAR}

			AND FILE_TYPE = #{fileType,jdbcType=VARCHAR}


			AND SEQNO_COMMENT IS NULL


			AND SEQNO_COMMENT = #{seqnoComment,jdbcType=VARCHAR}

		ORDER BY s1.CREATE_TIME ASC

mapper.update:
UPDATE sys_upload_file_info SET seqno_comment = #{seqno,jdbcType=VARCHAR}
WHERE FILE_TYPE = '03'
AND BUSINESS_ID = #{infoSeqno,jdbcType=VARCHAR}
AND seqno_comment IS NULL

mapper.select:
		select s2.node_id from sys_wfl_business_list s1
        inner join sys_wfl_business_node s2 on s1.workflow_id = s2.workflow_id
        where s2.his_no='1' and s1.seq_no = #{seqNo,jdbcType=VARCHAR}

mapper.delete:
DELETE FROM sys_upload_file_info
WHERE FILE_TYPE ='03' and seqno_comment IS NULL
AND BUSINESS_ID = #{businessId,jdbcType=VARCHAR}
